package com.amora.app;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.media.*;import android.media.session.*;import android.os.*;import org.json.*;
public class MusicService extends Service {
 static volatile MusicService active;MediaPlayer player;MediaSession session;String url="",title="",owner="";boolean desired=false,prepared=false;long position=0;AudioManager audio;AudioFocusRequest focus;final Handler handler=new Handler(Looper.getMainLooper());final java.util.concurrent.ExecutorService io=java.util.concurrent.Executors.newSingleThreadExecutor();boolean running=true,syncing=false;
 final Runnable poll=new Runnable(){public void run(){if(!running)return;if(!syncing){syncing=true;io.execute(()->{try{JSONObject data=AmoraApi.call(MusicService.this,new JSONObject().put("action","music"));JSONObject state=data.optJSONObject("session"),track=null;JSONArray queue=data.optJSONArray("queue");for(int i=0;state!=null&&queue!=null&&i<queue.length();i++)if(queue.getJSONObject(i).getString("id").equals(state.optString("track_id")))track=queue.getJSONObject(i);if(!running)return;if(track==null||!"audio".equals(track.optString("provider"))||!owner.equals(new JSONObject(SecureStore.get(MusicService.this)).optString("user"))){handler.post(()->stopSelf());return;}double expected=state.optDouble("position")+(state.optBoolean("playing")?(java.time.Instant.parse(data.getString("server_time")).toEpochMilli()-java.time.Instant.parse(state.getString("updated_at")).toEpochMilli())/1000.0:0);JSONObject command=new JSONObject().put("url",track.getString("url")).put("title",track.getString("title")).put("playing",state.optBoolean("playing")).put("position",expected);handler.post(()->{if(running)onStartCommand(new Intent().putExtra("data",command.toString()),0,0);});}catch(Exception e){if(e.getMessage()!=null&&(e.getMessage().contains("HTTP 401")||e.getMessage().contains("HTTP 403")||e.getMessage().contains("HTTP 400")))handler.post(()->stopSelf());}finally{handler.post(()->syncing=false);}});}handler.postDelayed(this,10000);}};
 @Override public void onCreate(){super.onCreate();active=this;audio=(AudioManager)getSystemService(AUDIO_SERVICE);session=new MediaSession(this,"AmoraMusic");session.setCallback(new MediaSession.Callback(){public void onPlay(){if(player!=null&&prepared){desired=true;startAudio();update();}}public void onPause(){pause();}public void onStop(){NativeBridge.event("musicStopped",true);stopSelf();}});session.setActive(true);handler.postDelayed(poll,10000);}
 void startAudio(){if(player==null||!prepared)return;try{if(focus==null)focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build()).setOnAudioFocusChangeListener(change->{if(change==AudioManager.AUDIOFOCUS_LOSS||change==AudioManager.AUDIOFOCUS_LOSS_TRANSIENT)pause();else if(change==AudioManager.AUDIOFOCUS_LOSS_TRANSIENT_CAN_DUCK&&player!=null)player.setVolume(.2f,.2f);else if(change==AudioManager.AUDIOFOCUS_GAIN&&player!=null)player.setVolume(1,1);}).build();if(audio.requestAudioFocus(focus)==AudioManager.AUDIOFOCUS_REQUEST_GRANTED)player.start();}catch(Exception e){NativeBridge.event("error","Não foi possível reproduzir o áudio.");}}
 @Override public int onStartCommand(Intent intent,int flags,int id){if(intent==null||"stop".equals(intent.getAction())){NativeBridge.event("musicStopped",true);stopSelf();return START_NOT_STICKY;}if("pause".equals(intent.getAction())){pause();return START_NOT_STICKY;}try{JSONObject data=new JSONObject(intent.getStringExtra("data"));String next=data.getString("url");android.net.Uri u=android.net.Uri.parse(next);if(!"https".equals(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null||!u.getPath().matches("(?i).*[.](mp3|m4a|ogg|wav|aac)$"))throw new Exception();title=data.optString("title","Nossa música");desired=data.optBoolean("playing");position=Math.max(0,Math.min(86400000,(long)(data.optDouble("position")*1000)));String uid=new JSONObject(SecureStore.get(this)).getString("user");if(!owner.isEmpty()&&!owner.equals(uid))releasePlayer();owner=uid;
 Notification n=notification();if(Build.VERSION.SDK_INT>=29)startForeground(270,n,ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PLAYBACK);else startForeground(270,n);
 if(!next.equals(url)||player==null){releasePlayer();url=next;player=new MediaPlayer();player.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());player.setDataSource(next);player.setOnPreparedListener(m->{prepared=true;m.seekTo((int)Math.min(position,Math.max(0,m.getDuration()-100)));if(desired)startAudio();update();});player.setOnCompletionListener(m->{desired=false;NativeBridge.event("musicEnded",true);advance();update();});player.setOnErrorListener((m,w,e)->{NativeBridge.event("error","O link de áudio não pôde ser reproduzido.");stopSelf();return true;});player.prepareAsync();}else if(prepared){if(Math.abs(player.getCurrentPosition()-position)>4000)player.seekTo((int)position);if(desired&&!player.isPlaying())startAudio();if(!desired&&player.isPlaying())player.pause();}update();
 }catch(Exception e){NativeBridge.event("error","Use um link HTTPS direto de áudio.");stopSelf();}return START_NOT_STICKY;}
 static JSONObject status(){JSONObject out=new JSONObject();try{MusicService s=active;if(s!=null&&s.player!=null&&s.prepared)out.put("musicPlaying",s.player.isPlaying()).put("musicPosition",s.player.getCurrentPosition());}catch(Exception ignored){}return out;}
 void advance(){final String endedUrl=url;io.execute(()->{try{JSONObject data=AmoraApi.call(this,new JSONObject().put("action","music")),s=data.optJSONObject("session");JSONArray q=data.optJSONArray("queue");if(!running||s==null||q==null||!s.optBoolean("playing"))return;for(int i=0;i<q.length();i++){JSONObject t=q.getJSONObject(i);if(t.getString("id").equals(s.optString("track_id"))&&endedUrl.equals(t.getString("url"))){JSONObject next=i+1<q.length()?q.getJSONObject(i+1):t;AmoraApi.call(this,new JSONObject().put("action","playback").put("id",next.getString("id")).put("playing",i+1<q.length()).put("position",0).put("revision",s.getInt("revision")));break;}}}catch(Exception ignored){}});}
 void pause(){desired=false;if(player!=null&&prepared&&player.isPlaying())player.pause();NativeBridge.event("musicPaused",true);update();stopSelf();}
 Notification notification(){NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("amora-music","Ouvindo juntos",NotificationManager.IMPORTANCE_LOW));PendingIntent open=PendingIntent.getActivity(this,270,new Intent(this,MainActivity.class).putExtra("route","music"),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT),stop=PendingIntent.getService(this,271,new Intent(this,MusicService.class).setAction("stop"),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT),pause=PendingIntent.getService(this,272,new Intent(this,MusicService.class).setAction("pause"),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);return new Notification.Builder(this,"amora-music").setSmallIcon(R.drawable.amora_icon).setContentTitle(title).setContentText("Ouvindo juntos · áudio próprio").setContentIntent(open).setOngoing(desired).addAction(new Notification.Action.Builder(null,"Pausar",pause).build()).addAction(new Notification.Action.Builder(null,"Parar",stop).build()).setStyle(new Notification.MediaStyle().setMediaSession(session.getSessionToken()).setShowActionsInCompactView(0,1)).build();}
 void update(){if(session!=null)session.setPlaybackState(new PlaybackState.Builder().setActions(PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_STOP).setState(desired?PlaybackState.STATE_PLAYING:PlaybackState.STATE_PAUSED,prepared&&player!=null?player.getCurrentPosition():0,desired?1:0).build());getSystemService(NotificationManager.class).notify(270,notification());}
 void releasePlayer(){prepared=false;if(player!=null){player.release();player=null;}url="";}
 @Override public void onDestroy(){running=false;handler.removeCallbacks(poll);io.shutdown();active=null;releasePlayer();if(focus!=null)audio.abandonAudioFocusRequest(focus);if(session!=null){session.setActive(false);session.release();}super.onDestroy();}
 @Override public IBinder onBind(Intent intent){return null;}
}
